import React from 'react';

import Globe2 from '@pohodnik/icons/svg/Communication/Globe2';
import Trophy from '@pohodnik/icons/svg/RealWorld/Trophy';
import clsx from 'clsx';

import { HikingBadgeOneLine } from '@apps/Hiking/@components/HikingBadge';
import { getWorkoutTypeColor } from '@apps/Workouts/@helpers/workouts.helper';
import { IWorkoutTarget } from '@apps/Workouts/@types/workoutsTargets.types';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge from '@ui-kit/Badge/Badge';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import WorkoutTypeIcon from '../WorkoutTypeIcon';

interface IWorkoutTargetItemProps extends React.HTMLAttributes<HTMLDivElement> {
  data: IWorkoutTarget;
}
const statFields: Array<keyof IWorkoutTarget> = [
  'distance',
  'alt_ascent',
  'alt_descent',
  'speed_max',
  'speed_min',
  'speed_avg',
  'hr_max',
  'hr_min',
  'hr_avg',
  'time_moving',
];

const statFieldsDisplay: {
  [k: string]: { label: string; processor?: (n: number) => string };
} = {
  distance: {
    label: 'Расстояние',
    processor(n) {
      return formatDistance(n);
    },
  },
  alt_ascent: {
    label: 'Набор высоты',
    processor(n) {
      return formatAltitude(n);
    },
  },
  alt_descent: {
    label: 'Сброс высоты',
    processor(n) {
      return formatAltitude(n);
    },
  },
  speed_max: {
    label: 'Скорость, max',
    processor(n) {
      return n.toFixed(1) + 'km/h';
    },
  },
  speed_min: {
    label: 'Скорость, min',
    processor(n) {
      return n.toFixed(1) + 'km/h';
    },
  },
  speed_avg: {
    label: 'Скорость, avg',
    processor(n) {
      return n.toFixed(1) + 'km/h';
    },
  },
  hr_max: {
    label: 'пульс, max',
    processor(n) {
      return n.toFixed(1) + 'bpm';
    },
  },
  hr_min: {
    label: 'пульс, min',
    processor(n) {
      return n.toFixed(1) + 'bpm';
    },
  },
  hr_avg: {
    label: 'пульс, avg',
    processor(n) {
      return n.toFixed(1) + 'bpm';
    },
  },
  time_moving: {
    label: 'Время в движении',
    processor(n) {
      return (n / 1000 / 60).toFixed(1) + 'ч.';
    },
  },
};

const WorkoutTargetItem: React.FC<IWorkoutTargetItemProps> = ({ data, className, ...rest }) => {
  return (
    <PohRow {...rest} className={clsx(className)}>
      <PohCol sm={6} md={3}>
        <strong className="mb-0 d-flex align-items-center">
          {data.type ? (
            <span style={{ color: getWorkoutTypeColor(data.type.id) }} title={data.type.name}>
              <WorkoutTypeIcon type={data.type} />
            </span>
          ) : (
            <span title="Все типы">
              <Trophy />
            </span>
          )}
          &nbsp;
          {data.name}
          {data.is_public && (
            <span className="ms-auto text-info" title="Публичный доступ">
              <Globe2 />
            </span>
          )}
        </strong>
        <small className="d-block">
          {dateRangeToLocaleString(data.date_start, data.date_finish)}
        </small>
      </PohCol>
      <PohCol sm={6} md={3}>
        {data.hiking && (
          <div className="mb-1">
            <HikingBadgeOneLine hiking={data.hiking} />
          </div>
        )}
        {statFields
          .filter((f) => !!data[f])
          .map((x) => (
            <PohBadge
              as="small"
              key={x}
              className="d-inline-block mr-1 text-start"
              style={{ lineHeight: 0.9 }}
            >
              <small className="text-muted d-block">{statFieldsDisplay[x].label}: </small>
              <strong className="text-success">
                {statFieldsDisplay[x].processor
                  ? statFieldsDisplay[x].processor(data[x] as number)
                  : (data[x] as string)}
              </strong>
            </PohBadge>
          ))}
      </PohCol>
      <PohCol sm={6} md={3} className="ms-auto text-end">
        <PohAva src={data.author.photo} />
      </PohCol>
    </PohRow>
  );
};

export default WorkoutTargetItem;
